"""Helper function that makes separate make_params
    for behavioral data

    Parameters
    ----------
    dataset : NWBDataset
        NWBDataset that the make_params are made for
    lag : int
        Amount that behavioral data is lagged relative to
        trial alignment in `make_params`
    make_params : dict
        Arguments for `NWBDataset.make_trial_data`
        to extract trialized data

    Returns
    -------
    dict
        Arguments for `NWBDataset.make_trial_data`
        to extract trialized behavior data
    """
def _prep_behavior(dataset: Any, lag: Any, make_params: Any) -> object {
    behavior_make_params = make_params.copy();
    if (lag is not None) {
        behavior_make_params['allow_nans'] = True;
        if ('align_range' in behavior_make_params) {
            behavior_make_params['align_range'] = `tuple(
                [(t + lag) for t in make_params['align_range']]
            );
        } else {
            behavior_make_params['align_range'] = (lag, lag);
        }
    } else {
        behavior_make_params = None;
    }
    return behavior_make_params;
}

"""Checks whether these points lie within the window of interest

    Points is a list of one start, one end coordinate (ints)
    """
def points_in_window(points: Any) -> object {
    if (
        (None in points)
        or (points[0] < -5)
        or (points[1] < -5)
        or (points[0] > 5)
        or (points[1] > 5)
    ) {
        return False;
    }
    return True;
}

"""
    Validates a video dictionary JSON from the client.

    Args:
        json_payload (dict): A JSON payload received from the client.

    Returns:
        bool: Whether or not the video JSON format was valid.
    """
def is_video_json_valid(json_payload: Any) -> object {
    if (not json_payload["videoUri"] or not json_payload["title"]) {
        return False;
    }
    return True;
}

