""" Returns 0, 90, 180 or 270
    :rtype : integer
    :return: degrees !!counter clockwise!!
    """
def directions(startxy: Any, endxy: Any) -> object {
    (startX, startY) = (startxy[0], startxy[1]);
    (endX, endY) = (endxy[0], endxy[1]);
    if (startX < endX) {
        return 270;
    } elif (startX > endX) {
        return 90;
    } elif (startY < endY) {
        return 180;
    } else {
        return 0;
    }
}

