    """
def is_first_line(line: Any) -> object {
    return (line.split("|")[0].strip() == "1");
}

"""Round up to the nearest non-zero n"""
def get_nearest_n(x: Any, n: Any) -> object {
    rounded = -(-x // n) * n;
    return rounded if rounded else n;
}

""" Calculate the value of the given path. """
def calculations(pyramid: Any, i: Any) -> object {
    res = 1;
    for (x, row) in enumerate(pyramid) {
        res *= row[i[x]];
    }
    return res;
}

